import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

sigmoid_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void sigmoid_kernel_vec4(const float4* __restrict__ x,
                                     float4* __restrict__ y,
                                     int n_vec4) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    for (int i = idx; i < n_vec4; i += stride) {
        float4 v = x[i];
        float4 r;
        r.x = 1.0f / (1.0f + __expf(-v.x));
        r.y = 1.0f / (1.0f + __expf(-v.y));
        r.z = 1.0f / (1.0f + __expf(-v.z));
        r.w = 1.0f / (1.0f + __expf(-v.w));
        y[i] = r;
    }
}

__global__ void sigmoid_kernel_scalar(const float* __restrict__ x,
                                       float* __restrict__ y,
                                       int n, int offset) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x + offset;
    if (idx < n) {
        y[idx] = 1.0f / (1.0f + __expf(-x[idx]));
    }
}

torch::Tensor sigmoid_cuda(torch::Tensor x) {
    auto x_contig = x.contiguous();
    auto y = torch::empty_like(x_contig);

    int64_t n = x_contig.numel();
    int64_t n_vec4 = n / 4;
    int64_t remainder_start = n_vec4 * 4;
    int64_t remainder = n - remainder_start;

    const float* x_ptr = x_contig.data_ptr<float>();
    float* y_ptr = y.data_ptr<float>();

    if (n_vec4 > 0) {
        const int threads = 256;
        int blocks = (int)((n_vec4 + threads - 1) / threads);
        if (blocks > 65535) blocks = 65535;
        sigmoid_kernel_vec4<<<blocks, threads>>>(
            reinterpret_cast<const float4*>(x_ptr),
            reinterpret_cast<float4*>(y_ptr),
            (int)n_vec4);
    }

    if (remainder > 0) {
        const int threads = 128;
        int blocks = (int)((remainder + threads - 1) / threads);
        sigmoid_kernel_scalar<<<blocks, threads>>>(x_ptr, y_ptr, (int)n, (int)remainder_start);
    }

    return y;
}
"""

sigmoid_cpp_source = "torch::Tensor sigmoid_cuda(torch::Tensor x);"

sigmoid_module = load_inline(
    name="sigmoid_module",
    cpp_sources=sigmoid_cpp_source,
    cuda_sources=sigmoid_source,
    functions=["sigmoid_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a Sigmoid activation using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.sigmoid_cuda = sigmoid_module.sigmoid_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.sigmoid_cuda(x)


batch_size = 4096
dim = 131072


def get_inputs():
    x = torch.rand(batch_size, dim)
    return [x]


def get_init_inputs():
